package com.bank.challenges.client;

import com.bank.challenges.model.Account;
import java.math.BigDecimal;
import java.util.Map;
import java.util.logging.Logger;

// In a monolith this was a direct method call. Across services it is a
// REMOTE call that can time out or fail — so it needs a circuit breaker.
public class AccountClient {
    private static final Logger log = Logger.getLogger(AccountClient.class.getName());
    private final Map<String, Account> remoteAccounts;
    private boolean accountServiceDown = false;

    public AccountClient(Map<String, Account> remoteAccounts) {
        this.remoteAccounts = remoteAccounts;
    }

    public void simulateOutage(boolean down) { this.accountServiceDown = down; }

    // @CircuitBreaker(name="accountService", fallbackMethod="debitFallback")
    public void debit(String accountId, BigDecimal amount) {
        if (accountServiceDown) {
            throw new RuntimeException("Account Service unavailable (network)");
        }
        log.info(() -> "REMOTE debit " + amount + " from " + accountId);
        remoteAccounts.get(accountId).debit(amount);
    }

    // @CircuitBreaker(name="accountService", fallbackMethod="creditFallback")
    public void credit(String accountId, BigDecimal amount) {
        if (accountServiceDown) {
            throw new RuntimeException("Account Service unavailable (network)");
        }
        log.info(() -> "REMOTE credit " + amount + " to " + accountId);
        remoteAccounts.get(accountId).credit(amount);
    }
}
