package com.bank.challenges.service;

import com.bank.challenges.client.AccountClient;
import java.math.BigDecimal;
import java.util.logging.Level;
import java.util.logging.Logger;

// There is NO single @Transactional across services. We run a SAGA:
// debit, then credit, and COMPENSATE (re-credit) if the credit step fails.
public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private final AccountClient accountClient;

    public TransferService(AccountClient accountClient) {
        this.accountClient = accountClient;
    }

    public String transfer(String fromId, String toId, BigDecimal amount) {
        // Step 1: debit sender
        try {
            accountClient.debit(fromId, amount);
        } catch (RuntimeException ex) {
            log.log(Level.SEVERE, "Debit failed, nothing to compensate", ex);
            return "FAILED";
        }
        // Step 2: credit receiver — if it fails, COMPENSATE the debit
        try {
            accountClient.credit(toId, amount);
        } catch (RuntimeException ex) {
            log.log(Level.SEVERE, "Credit failed — compensating by re-crediting sender", ex);
            accountClient.credit(fromId, amount); // compensating action
            return "COMPENSATED";
        }
        log.info(() -> "Transfer SUCCESS " + fromId + " to " + toId + " amount " + amount);
        return "COMPLETED";
    }
}
