package com.bank.challenges;

import com.bank.challenges.client.AccountClient;
import com.bank.challenges.model.Account;
import com.bank.challenges.service.TransferService;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

public class MonolithVsMicroservicesDemo {
    private static final Logger log = Logger.getLogger(MonolithVsMicroservicesDemo.class.getName());

    public static void main(String[] args) {
        Map<String, Account> accounts = new HashMap<>();
        accounts.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        accounts.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));

        AccountClient client = new AccountClient(accounts);
        TransferService service = new TransferService(client);
        BigDecimal rentAmount = new BigDecimal("50000");

        log.info("=== Healthy path (both services up) ===");
        service.transfer("SAV2001", "CUR3001", rentAmount);
        log.info("Rajesh=" + accounts.get("SAV2001").getBalance()
               + " Priya=" + accounts.get("CUR3001").getBalance());

        log.info("=== Partial failure (Account Service down) ===");
        client.simulateOutage(true);
        String result = service.transfer("SAV2001", "CUR3001", rentAmount);
        log.info("Result when service down: " + result);
    }
}
